#!/usr/bin/env bash
# step93 — Phase 4b (async): adapt trials to the bot's two-step generation.
# botapi.trialStatus, claim becomes fire-and-forget (stores request_id), and a
# background poller (lib/trialpoll.js) polls /api/trial-status and delivers
# credentials when ready. Requires step91+step92. Idempotent; rolls back.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step93-$TS
mkdir -p "$BAK/routes" "$BAK/lib"
cp "$APP/lib/botapi.js" "$BAK/lib/botapi.js"
cp "$APP/server.js" "$BAK/server.js"
cp "$APP/routes/trials.js" "$BAK/routes/trials.js"
restore(){ echo "!! rollback"; cp "$BAK/lib/botapi.js" "$APP/lib/botapi.js"; cp "$BAK/server.js" "$APP/server.js"; cp "$BAK/routes/trials.js" "$APP/routes/trials.js"; rm -f "$APP/lib/trialpoll.js"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> patch botapi (trialStatus)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/lib/botapi.js'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('trialStatus')>=0){ console.log('   botapi already'); }
else {
  const a="function generateTrial(payload) { return req('POST', '/api/generate-trial', payload, 15000); }";
  if(s.indexOf(a)<0){ console.error('!! generateTrial anchor not found (deploy step91 first)'); process.exit(2); }
  s=s.replace(a, a+"\nfunction trialStatus(rid) { return req('GET', '/api/trial-status/' + encodeURIComponent(rid), null, 8000); }");
  const e=", generateTrial };";
  if(s.indexOf(e)<0){ console.error('!! export anchor not found'); process.exit(3); }
  s=s.replace(e, ", generateTrial, trialStatus };");
  fs.writeFileSync(f,s); console.log('   botapi patched');
}
NODE

echo "==> overwrite routes/trials.js (async claim) + write lib/trialpoll.js"
base64 -d > "$APP/routes/trials.js" <<'B64'

B64
base64 -d > "$APP/lib/trialpoll.js" <<'B64'

B64

echo "==> patch server.js (start trial poller)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/server.js'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('trialpoll')>=0){ console.log('   server already'); }
else {
  const a="try { require('./lib/wanotify')(pool).startWorker(); } catch (e) { console.log('[wanotify] ' + e.message); }";
  if(s.indexOf(a)<0){ console.error('!! wanotify start anchor not found (deploy step81 first)'); process.exit(4); }
  s=s.replace(a, a+"\ntry { require('./lib/trialpoll')(pool).startWorker(); } catch (e) { console.log('[trialpoll] ' + e.message); }");
  fs.writeFileSync(f,s); console.log('   server patched');
}
NODE

echo "==> node --check + restart + health"
node --check "$APP/lib/botapi.js"; node --check "$APP/lib/trialpoll.js"; node --check "$APP/routes/trials.js"; node --check "$APP/server.js"
pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
grep -q '</html>' <<<"$(curl -s -m 12 http://127.0.0.1:3900/trials || true)" || { echo "!! /trials not rendering"; false; }
trap - ERR
echo "==> step93 OK — async trial generation + poller live. Backup: $BAK"
echo "   Claim is instant ('being prepared'); poller delivers credentials when the bot finishes (~10-30s)."
